        // earns its first miss and stays pending.
        let generation = native
            .scene
            .coordinator
            .adapter
            .record(caller)
            .map(|record| crate::inspect_system::MemberGeneration {
                start_time: record.start_time,
                exe: record.exe.clone(),
            });
