    #[test]
    fn a_recorded_reuse_without_an_admitted_successor_leaves_the_coordinator_row_unbound() {
        // The pid turns over between passes (the pin dies while the pid
        // names a live process) but the successor admission fails on the
        // caller budget: one retained holder with an in-lifetime row, yet
        // the recorded reuse voids it.
        let (mut native, _) = watched_native();
        native.scene.coordinator.adapter.set_max_callers(1);
        native.scene.source.kill(7);
        native.scene.source.spawn(7, 600);
        let observed: BTreeSet<u32> = BTreeSet::from([7]);
        let events = native.scene.coordinator.adapter.reconcile(
            &observed,
            &mut |_| ImageAuthority::ScanPinned,
            500,
        );
        // Two refusals: the post-reuse re-admission plus the observed
        // sweep, both over budget.
        assert_eq!(events.len(), 2);
        assert!(
            events
                .iter()
                .all(|event| matches!(event, CallerEvent::AdmitFailed { pid: 7, .. })),
            "{events:?}"
        );
        native
            .scene
            .coordinator
            .apply_reconcile_events(&events, 500);
        assert!(native.scene.coordinator.adapter.live_id(7).is_none());
        let row = native.row(41, 1, 7, 400, 0);
        native.witness(vec![row]);
        let census = native.scene.coordinator.registry.witness_census();
        assert_eq!(census.bound, 0);
        assert_eq!(census.unbound.get(&UnboundReason::NoLiveCaller), Some(&1));
    }

    #[test]
    fn a_reuse_recorded_between_read_and_settle_leaves_the_coordinator_row_unbound() {
        // The row is read with one holder (the live pin dies during the
        // query), then the pid turns over and the successor admits: the
        // reuse recorded before the decision voids the retained snapshot.
        let (mut native, _) = watched_native();
        native.query_answer(7, 500, CookieQuery::Exited);
        let row = native.row(41, 1, 7, 400, 0);
        native.read(vec![row]);
        native.scene.source.kill(7);
        native.scene.source.spawn(7, 600);
        let observed: BTreeSet<u32> = BTreeSet::from([7]);
        let events = native.scene.coordinator.adapter.reconcile_detected(
            &observed,
            &mut |_| ImageAuthority::ScanPinned,
            500,
            &mut || Some(500),
        );
        assert_eq!(events.len(), 1);
        assert!(
            matches!(events[0], CallerEvent::Reused { .. }),
            "{events:?}"
        );
        native
            .scene
            .coordinator
            .apply_reconcile_events(&events, 500);
        native.drain();
        native.stage(native.stamps.read(native.domain, Vec::new()));
        native.scene.coordinator.commit_batch(false).unwrap();
        let census = native.scene.coordinator.registry.witness_census();
        assert_eq!(census.bound, 0);
        assert_eq!(census.unbound.get(&UnboundReason::CallerExited), Some(&1));
    }

    #[test]
    fn pid_reuse_reaches_the_binder_under_pid_scope_only() {
        // The retained fallback runs under PID scope only, so only PID
        // turnovers are forwarded; system/cgroup scopes never grow the
        // binder's reuse table.
        for (scope, want) in [(Scope::Pid(std::process::id()), 1), (Scope::System, 0)] {
            let (mut native, _) = watched_native();
            native.scene.coordinator.engine.scope = scope.clone();
            native.scene.source.kill(7);
            native.scene.source.spawn(7, 600);
            let observed: BTreeSet<u32> = BTreeSet::from([7]);
            let events = native.scene.coordinator.adapter.reconcile_detected(
                &observed,
                &mut |_| ImageAuthority::ScanPinned,
                500,
                &mut || Some(500),
            );
            assert_eq!(events.len(), 1, "{scope:?}");
            native
                .scene
                .coordinator
                .apply_reconcile_events(&events, 500);
            assert_eq!(
                native.scene.coordinator.binder.reuse_len_for_test(),
                want,
                "{scope:?} forwards recorded reuses"
            );
        }
    }

    #[test]
    fn a_counted_edge_after_a_clean_pid_exit_names_the_exit_not_dropped_records() {
        // A clean PID-target exit ends the count: the edge reads counted
        // (a lower bound), but the wording names the exit — no records
        // were dropped.
        let mut scene = CaptureScene::new(2);
        scene.source.spawn(7, 500);
        let caller = scene
            .coordinator
            .adapter
            .admit(7, ImageAuthority::ScanPinned, 50)
            .unwrap();
        scene
            .coordinator
            .begin_capture_coverage(CaptureScopeCoverage::Pid(
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ));
        let mut native = NativeScene::over(scene, 0);
        native.scene.attach_all(100, ScopeCustody::PidHeld);
        native.scene.project(7, 120);
        native.scene.coordinator.commit_batch(false).unwrap();
        native.answer(7, 500, 41);
        let row = native.row(41, 1, 7, 200, 0);
        native.witness(vec![row]);
        assert!(
            matches!(
                native.scene.coverage(caller),
                UseCoverage::Counted { lossy: false, .. }
            ),
            "{:?}",
            native.scene.coverage(caller)
        );
        let custody = ScopeCustody::PidExited {
            at_ns: 600,
            proof: crate::attach::capture::OriginalPidExit::scripted(
                native.domain,
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ),
        };
        native.scene.coordinator.note_capture_custody(&custody);
        native.scene.coordinator.commit_batch(false).unwrap();
        let coverage = native.scene.coverage(caller);
        assert!(
            matches!(coverage, UseCoverage::Counted { lossy: true, .. }),
            "{coverage:?}"
        );
        assert_eq!(
            crate::inventory_present::coverage_label_at(&coverage, 3_000),
            "counted until the PID target exited (lower bound)"
        );
    }

    #[test]
    fn a_later_loss_after_a_clean_pid_exit_clears_the_exit_claim() {
        // A clean exit names the exit as the sole loss cause; a later
        // generic loss (an exec the drain found after the exit) clears
        // the claim: the coverage no longer carries pid_exit and the
        // label no longer names the exit.
        let mut scene = CaptureScene::new(2);
        scene.source.spawn(7, 500);
        let caller = scene
            .coordinator
            .adapter
            .admit(7, ImageAuthority::ScanPinned, 50)
            .unwrap();
        scene
            .coordinator
            .begin_capture_coverage(CaptureScopeCoverage::Pid(
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ));
        let mut native = NativeScene::over(scene, 0);
        native.scene.attach_all(100, ScopeCustody::PidHeld);
        native.scene.project(7, 120);
        native.scene.coordinator.commit_batch(false).unwrap();
        native.answer(7, 500, 41);
        let row = native.row(41, 1, 7, 200, 0);
        native.witness(vec![row]);
        let custody = ScopeCustody::PidExited {
            at_ns: 600,
            proof: crate::attach::capture::OriginalPidExit::scripted(
                native.domain,
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ),
        };
        native.scene.coordinator.note_capture_custody(&custody);
        native.scene.coordinator.commit_batch(false).unwrap();
        let coverage = native.scene.coverage(caller);
        assert!(
            matches!(
                coverage,
                UseCoverage::Counted {
                    lossy: true,
                    pid_exit: true,
                    ..
                }
            ),
            "{coverage:?}"
        );
        assert_eq!(
            crate::inventory_present::coverage_label_at(&coverage, 3_000),
            "counted until the PID target exited (lower bound)"
        );
        // A later generic loss: an exec of the PID target the drain
        // found after the exit proof folded.
        let lost = ScopeCustody::PidLost {
            at_ns: 700,
            reason: "PID custody lost: an exec of the PID target was observed".into(),
        };
        native.scene.coordinator.note_capture_custody(&lost);
        native.scene.coordinator.commit_batch(false).unwrap();
        let coverage = native.scene.coverage(caller);
        assert!(
            matches!(
                coverage,
                UseCoverage::Counted {
                    lossy: true,
                    pid_exit: false,
                    ..
                }
            ),
            "a later loss must clear the exit-only claim: {coverage:?}"
        );
        assert_ne!(
            crate::inventory_present::coverage_label_at(&coverage, 3_000),
            "counted until the PID target exited (lower bound)"
        );
    }

    #[test]
    fn a_later_lifecycle_loss_after_a_clean_pid_exit_clears_the_exit_claim() {
        // Same revocation through the lifecycle-loss path: a clean exit
        // followed by lost lifecycle evidence clears the exit-only claim.
        let mut scene = CaptureScene::new(2);
        scene.source.spawn(7, 500);
        let caller = scene
            .coordinator
            .adapter
            .admit(7, ImageAuthority::ScanPinned, 50)
            .unwrap();
        scene
            .coordinator
            .begin_capture_coverage(CaptureScopeCoverage::Pid(
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ));
        let mut native = NativeScene::over(scene, 0);
        native.scene.attach_all(100, ScopeCustody::PidHeld);
        native.scene.project(7, 120);
        native.scene.coordinator.commit_batch(false).unwrap();
        native.answer(7, 500, 41);
        let row = native.row(41, 1, 7, 200, 0);
        native.witness(vec![row]);
        let custody = ScopeCustody::PidExited {
            at_ns: 600,
            proof: crate::attach::capture::OriginalPidExit::scripted(
                native.domain,
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ),
        };
        native.scene.coordinator.note_capture_custody(&custody);
        native.scene.coordinator.commit_batch(false).unwrap();
        assert!(
            matches!(
                native.scene.coverage(caller),
                UseCoverage::Counted {
                    lossy: true,
                    pid_exit: true,
                    ..
                }
            ),
            "{:?}",
            native.scene.coverage(caller)
        );
        native
            .scene
            .coordinator
            .note_lifecycle_loss(&crate::attach::capture::LifecycleLoss {
                at_ns: 700,
                reason: "DISCOVERY ring loss hid an exec of the PID target".into(),
            });
        native.scene.coordinator.commit_batch(false).unwrap();
        let coverage = native.scene.coverage(caller);
        assert!(
            matches!(
                coverage,
                UseCoverage::Counted {
                    lossy: true,
                    pid_exit: false,
                    ..
                }
            ),
            "a later lifecycle loss must clear the exit-only claim: {coverage:?}"
        );
        assert_ne!(
            crate::inventory_present::coverage_label_at(&coverage, 3_000),
            "counted until the PID target exited (lower bound)"
        );
    }

    #[test]
    fn a_later_loss_after_a_clean_pid_exit_records_a_gap_naming_that_loss() {
        // The exit claim is revoked by a later generic loss: the
        // revocation records a gap under "native capture scope custody
        // unproven" naming the later loss, next to the first-loss gap.
        let mut scene = CaptureScene::new(2);
        scene.source.spawn(7, 500);
        scene
            .coordinator
            .adapter
            .admit(7, ImageAuthority::ScanPinned, 50)
            .unwrap();
        scene
            .coordinator
            .begin_capture_coverage(CaptureScopeCoverage::Pid(
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ));
        let mut native = NativeScene::over(scene, 0);
        native.scene.attach_all(100, ScopeCustody::PidHeld);
        native.scene.project(7, 120);
        native.scene.coordinator.commit_batch(false).unwrap();
        native.answer(7, 500, 41);
        let row = native.row(41, 1, 7, 200, 0);
        native.witness(vec![row]);
        let custody = ScopeCustody::PidExited {
            at_ns: 600,
            proof: crate::attach::capture::OriginalPidExit::scripted(
                native.domain,
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ),
        };
        native.scene.coordinator.note_capture_custody(&custody);
        native.scene.coordinator.commit_batch(false).unwrap();
        let lost = ScopeCustody::PidLost {
            at_ns: 700,
            reason: "PID custody lost: an exec of the PID target was observed".into(),
        };
        native.scene.coordinator.note_capture_custody(&lost);
        native.scene.coordinator.commit_batch(false).unwrap();
        let gaps: Vec<_> = native
            .scene
            .coordinator
            .registry
            .gaps()
            .iter()
            .filter(|gap| gap.subject == "native capture scope custody unproven")
            .collect();
        assert_eq!(gaps.len(), 2, "the exit gap plus the later-loss gap");
        assert!(
            gaps.iter().any(|gap| gap
                .reason
                .contains("an exec of the PID target was observed")
                && gap.reason.contains("withdrawn")),
            "the later gap names the later loss and the withdrawn claim: {gaps:?}"
        );
    }

    #[test]
    fn a_superseding_exit_proof_revokes_the_registry_exit_claim() {
        // A later exit proof that differs from the folded one clears the
        // coordinator copy, so the registry's exit-only claim is revoked
        // too — and the revocation is disclosed.
        let mut scene = CaptureScene::new(2);
        scene.source.spawn(7, 500);
        let caller = scene
            .coordinator
            .adapter
            .admit(7, ImageAuthority::ScanPinned, 50)
            .unwrap();
        scene
            .coordinator
            .begin_capture_coverage(CaptureScopeCoverage::Pid(
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ));
        let mut native = NativeScene::over(scene, 0);
        native.scene.attach_all(100, ScopeCustody::PidHeld);
        native.scene.project(7, 120);
        native.scene.coordinator.commit_batch(false).unwrap();
        native.answer(7, 500, 41);
        let row = native.row(41, 1, 7, 200, 0);
        native.witness(vec![row]);
        let custody = ScopeCustody::PidExited {
            at_ns: 600,
            proof: crate::attach::capture::OriginalPidExit::scripted(
                native.domain,
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ),
        };
        native.scene.coordinator.note_capture_custody(&custody);
        native.scene.coordinator.commit_batch(false).unwrap();
        assert!(
            matches!(
                native.scene.coverage(caller),
                UseCoverage::Counted {
                    lossy: true,
                    pid_exit: true,
                    ..
                }
            ),
            "{:?}",
            native.scene.coverage(caller)
        );
        let later = ScopeCustody::PidExited {
            at_ns: 700,
            proof: crate::attach::capture::OriginalPidExit::scripted(
                NativeDomainId::mint(),
                crate::attach::capture::ScopeIncarnation {
                    pid: 7,
                    start_time: Some(500),
                },
            ),
        };
        native.scene.coordinator.note_capture_custody(&later);
        native.scene.coordinator.commit_batch(false).unwrap();
        let coverage = native.scene.coverage(caller);
        assert!(
            matches!(
                coverage,
                UseCoverage::Counted {
                    lossy: true,
                    pid_exit: false,
                    ..
                }
            ),
            "a superseding exit proof must clear the exit-only claim: {coverage:?}"
        );
        assert_ne!(
            crate::inventory_present::coverage_label_at(&coverage, 3_000),
            "counted until the PID target exited (lower bound)"
        );
        assert!(
            native
                .scene
                .coordinator
                .registry
                .gaps()
                .iter()
                .any(|gap| gap.subject == "native capture scope custody unproven"
                    && gap.reason.contains("superseded")),
            "the supersede revocation is disclosed"
        );
    }

    /// Slice-1 views: the concise snapshot and the JSON document.
    fn slice_one_views(native: &NativeScene) -> (String, serde_json::Value) {
        let presentation = crate::inventory_present::Presentation::capture(
            &native.scene.coordinator,
            "native",
            0,
            2_000,
            1,
        );
        let text = crate::inventory_present::render_snapshot_with_verbosity(
            &presentation,
            crate::cli::TextVerbosity::Concise,
        );
        let document =
            crate::inventory::render_json(&native.scene.coordinator, "native", 0, 2_000, 1);
        (text, document)
    }

    /// Slice 1: a scan-less one-shot (never admitted, no scan pass)
    /// counts one unidentified caller with its lower-bound calls, in
    /// concise text and JSON.
    #[test]
    fn a_scan_less_one_shot_counts_one_unidentified_caller() {
        let (mut native, _) = NativeScene::new();
        let row = native.row(41, 1, 9, 210, 0);
        native.witness(vec![row]);
        let (text, document) = slice_one_views(&native);
        assert_eq!(document["modules"][0]["unbound_use"]["images"], 1);
        assert_eq!(
            document["modules"][0]["unbound_use"]["images_saturated"],
            false
        );
        assert_eq!(
            document["observation"]["native_witnesses"]["unbound_images"],
            1
        );
        let line = "unidentified callers: at least 1 call from 1 caller process never identified (exited or never scanned); host pids 9 (not running now or never scanned)";
        assert!(
            text.lines().any(|candidate| candidate == line),
            "concise names the caller:\n{text}"
        );
    }

    /// Slice 1: one tgid, two task cookies — two caller processes.
    #[test]
    fn one_tgid_two_cookies_counts_two_unidentified_callers() {
        let (mut native, _) = NativeScene::new();
        let first = native.row(41, 1, 9, 210, 0);
        let second = native.row(42, 1, 9, 220, 0);
        native.witness(vec![first, second]);
        let (text, document) = slice_one_views(&native);
        assert_eq!(document["modules"][0]["unbound_use"]["images"], 2);
        assert_eq!(
            document["observation"]["native_witnesses"]["unbound_images"],
            2
        );
        let line = "unidentified callers: at least 2 calls from 2 caller processes never identified (exited or never scanned); host pids 9, 9 (not running now or never scanned)";
        assert!(
            text.lines().any(|candidate| candidate == line),
            "concise names both callers:\n{text}"
        );
    }

    /// Slice 1 twin: a scanned caller binds its row to an edge and
    /// counts no unidentified caller.
    #[test]
    fn a_scanned_caller_binds_and_counts_no_unidentified_caller() {
        let (mut native, _) = NativeScene::new();
        native.scene.source.spawn(9, 900);
        native
            .scene
            .coordinator
            .adapter
            .admit(9, ImageAuthority::ScanPinned, 100)
            .unwrap();
        native.scene.project(9, 110);
        native.answer(9, 900, 41);
        let row = native.row(41, 1, 9, 210, 0);
        native.witness(vec![row]);
        let census = native.scene.coordinator.registry.witness_census().clone();
        assert_eq!((census.rows, census.bound, census.pending), (1, 1, 0));
        let (text, document) = slice_one_views(&native);
        assert!(document["modules"][0]["unbound_use"].is_null());
        assert_eq!(
            document["observation"]["native_witnesses"]["unbound_images"],
            0
        );
        assert!(
            !text.contains("unidentified callers:"),
            "no unidentified caller reads nothing:\n{text}"
        );
    }

    /// Slice 1: one task cookie across an exec chain (two exec ids)
    /// is one caller process.
    #[test]
    fn one_cookie_two_exec_ids_counts_one_unidentified_caller() {
        let (mut native, _) = NativeScene::new();
        let first = native.row(41, 1, 9, 210, 0);
        let second = native.row(41, 2, 9, 220, 0);
        native.witness(vec![first, second]);
        let (text, document) = slice_one_views(&native);
        assert_eq!(document["modules"][0]["unbound_use"]["images"], 1);
        assert_eq!(
            document["observation"]["native_witnesses"]["unbound_images"],
            1
        );
        let line = "unidentified callers: at least 2 calls from 1 caller process never identified (exited or never scanned); host pids 9 (not running now or never scanned)";
        assert!(
            text.lines().any(|candidate| candidate == line),
            "one cookie is one caller:\n{text}"
        );
    }

    impl NativeScene {
        pub(super) fn execs(&mut self, records: Vec<p11scope_ebpf_common::DiscoveryRecord>) {
            let at = self.stamps.tick();
            let batch = DiscoveryBatch::scripted(self.domain, records, at);
            self.stage(NativeBatch::Lifecycle(batch));
        }
    }

    /// One staged EXEC record carrying `ticket` and `(dev, ino)`.
    fn exec_record(
        ticket: u64,
        tgid: u32,
        hook: u64,
        dev: u64,
        ino: u64,
    ) -> p11scope_ebpf_common::DiscoveryRecord {
        // SAFETY: DiscoveryRecord contains only integer fields; this
        // is the same fixed EXEC wire shape the producer emits.
        let mut record: p11scope_ebpf_common::DiscoveryRecord = unsafe { std::mem::zeroed() };
        record.kind = p11scope_ebpf_common::DISCOVERY_KIND_EXEC;
        record.pid_tgid = (u64::from(tgid) << 32) | u64::from(tgid);
        record.hook_ts_ns = hook;
        record.binding_id = ticket;
        record.pointers[0] = dev;
        record.pointers[1] = ino;
        record
    }

    fn scene_unbound_exe(native: &NativeScene) -> Vec<UnboundExe> {
        native
            .scene
            .coordinator
            .registry
            .unidentified_pids()
            .iter()
            .map(|pid| pid.exe.clone())
            .collect()
    }

    /// The EXEC-before-row order: the row's domain-tagged cookie
    /// meets the EXEC's ticket in the same domain, and the image
    /// keeps the EXEC's `(dev, ino)`.
    #[test]
    fn exec_before_row_joins_exe_pair_to_the_image() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.execs(vec![exec_record(41, 9, 100, 8, 99)]);
        native.witness(vec![native.row(41, 1, 9, 210, 0)]);
        let exes = scene_unbound_exe(&native);
        assert_eq!(exes.len(), 1);
        assert_eq!(exes[0].dev, 8);
        assert_eq!(exes[0].ino, 99);
        assert_eq!(exes[0].resolution, ExeResolution::PathUnknown);
        assert_eq!(exes[0].path, None);
    }

    /// The row-before-EXEC order (the CALLER_USE map read won the
    /// race against the EXEC ring drain): the EXEC backfills the
    /// already-staged image.
    #[test]
    fn row_before_exec_backfills_exe_pair_to_the_image() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.witness(vec![native.row(41, 1, 9, 210, 0)]);
        native.execs(vec![exec_record(41, 9, 100, 8, 99)]);
        let exes = scene_unbound_exe(&native);
        assert_eq!(exes.len(), 1);
        assert_eq!((exes[0].dev, exes[0].ino), (8, 99));
        assert_eq!(exes[0].resolution, ExeResolution::PathUnknown);
    }

    /// The join is the exact typed pair: another ticket, another
    /// domain, or a zero (unavailable) ticket never joins — even
    /// when the pid matches. Never a bare-PID join.
    #[test]
    fn exe_join_needs_the_same_domain_and_ticket() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.execs(vec![
            exec_record(41, 9, 100, 8, 99),
            exec_record(0, 9, 100, 8, 1000),
        ]);
        native.witness(vec![native.row(42, 1, 9, 210, 0)]);
        let other = NativeDomainId::mint();
        let endpoint = native.scene.delta.endpoints[0];
        let foreign = WitnessRow::scripted(other, 41, 1, endpoint.object, endpoint.id, 9, 210);
        // The full read/drain/read/commit protocol per domain: the
        // trailing empty read closes the horizons so the row decides.
        native.stage(native.stamps.read(other, vec![foreign]));
        native.stage(native.stamps.drain(other));
        native.stage(native.stamps.read(other, Vec::new()));
        native.scene.coordinator.commit_batch(false).unwrap();
        let exes = scene_unbound_exe(&native);
        assert_eq!(exes.len(), 2);
        for exe in &exes {
            assert_eq!(
                (exe.dev, exe.ino, exe.path.clone(), exe.resolution),
                (0, 0, None, ExeResolution::NoExecRecord),
                "unjoined images stay provisionally unjoined: {exe:?}"
            );
        }
    }

    /// A joined `(0, 0)` pair means the kernel read failed: the
    /// image reads unavailable, never missing (the EXEC arrived —
    /// loss accounting must not claim it).
    #[test]
    fn zero_exe_pair_reads_unavailable_not_missing() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.execs(vec![exec_record(41, 9, 100, 0, 0)]);
        native.witness(vec![native.row(41, 1, 9, 210, 0)]);
        let exes = scene_unbound_exe(&native);
        assert_eq!(exes.len(), 1);
        assert_eq!(
            (exes[0].dev, exes[0].ino, exes[0].resolution),
            (0, 0, ExeResolution::ExeUnavailable)
        );
    }

    /// A re-exec keeps its ticket: the latest EXEC wins the pair.
    #[test]
    fn reexec_keeps_latest_exe_pair() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.execs(vec![
            exec_record(41, 9, 100, 8, 99),
            exec_record(41, 9, 150, 8, 1000),
        ]);
        native.witness(vec![native.row(41, 1, 9, 210, 0)]);
        let exes = scene_unbound_exe(&native);
        assert_eq!(exes.len(), 1);
        assert_eq!((exes[0].dev, exes[0].ino), (8, 1000));
    }

    /// Lifecycle loss flips the domain's still-unjoined images to
    /// `exec_record_lost`; joined pairs are unaffected.
    #[test]
    fn lifecycle_loss_flips_unjoined_images_to_exec_lost() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.execs(vec![exec_record(41, 9, 100, 8, 99)]);
        native.witness(vec![
            native.row(41, 1, 9, 210, 0),
            native.row(42, 1, 10, 220, 0),
        ]);
        let at = native.stamps.tick();
        let mut lost = DiscoveryBatch::scripted(native.domain, Vec::new(), at);
        lost.failure = Some("scripted lifecycle loss".into());
        native.stage(NativeBatch::Lifecycle(lost));
        let pids = native.scene.coordinator.registry.unidentified_pids();
        assert_eq!(pids.len(), 2);
        let by_pid: std::collections::HashMap<u32, _> =
            pids.iter().map(|pid| (pid.pid_host, pid)).collect();
        assert_eq!(
            (by_pid[&9].exe.dev, by_pid[&9].exe.ino),
            (8, 99),
            "the joined image keeps its pair"
        );
        assert_eq!(
            by_pid[&10].exe,
            UnboundExe {
                dev: 0,
                ino: 0,
                path: None,
                resolution: ExeResolution::ExecRecordLost,
                identity_candidates: Vec::new(),
            }
        );
    }

    /// Discovery ring loss observed on a witness read flips the
    /// domain's unjoined images too: a lost ring record may be the
    /// image's EXEC.
    #[test]
    fn discovery_ring_loss_flips_unjoined_images_to_exec_lost() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        let row = native.row(41, 1, 9, 210, 0);
        native.witness(vec![row]);
        let at = native.stamps.tick();
        let mut batch = witness_batch();
        batch.domain = native.domain;
        batch.health.discovery_counters = Some([1, 0, 0, 0, 0]);
        batch.health_read_ns = at;
        batch.rows_anchor_ns = at + 1;
        batch.rows_read_ns = at + 1;
        batch.counts_read_ns = at + 1;
        native.stage(NativeBatch::Witness(Box::new(batch)));
        let pids = native.scene.coordinator.registry.unidentified_pids();
        assert_eq!(pids.len(), 1);
        assert_eq!(pids[0].exe.resolution, ExeResolution::ExecRecordLost);
    }

    /// The EXEC stash is bounded: past the cap, records shed, the
    /// shed counts, and the domain latches loss (the shed record
    /// may be the image's EXEC).
    #[test]
    fn exec_stash_saturation_sheds_and_counts() {
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        native.scene.coordinator.set_exec_stash_cap(2);
        native.execs(vec![
            exec_record(41, 9, 100, 8, 99),
            exec_record(42, 10, 100, 8, 100),
            exec_record(43, 11, 100, 8, 101),
        ]);
        assert_eq!(native.scene.coordinator.exec_exe_shed(), 1);
        native.witness(vec![native.row(43, 1, 11, 210, 0)]);
        let pids = native.scene.coordinator.registry.unidentified_pids();
        assert_eq!(pids.len(), 1);
        assert_eq!(pids[0].exe.resolution, ExeResolution::ExecRecordLost);
    }

    /// Resolution source (b): the coordinator exposes the
    /// scan-learned exe identities of admitted callers by their
    /// maps-domain `(dev, ino)`, probing each distinct path once per
    /// capture through the sticky cache. A caller whose path probes
    /// nothing (a placeholder or a deleted binary) contributes
    /// nothing.
    #[test]
    fn scan_learned_exe_map_names_admitted_callers() {
        let dir = tempfile::tempdir().unwrap();
        let (path, dev, ino) = staged_tool(&dir, "tool-a");
        let (mut native, _) = NativeScene::new();
        native.scene.source.spawn(9, 900);
        native.scene.source.exec(9, 101, path.to_str().unwrap());
        native
            .scene
            .coordinator
            .adapter
            .admit(9, ImageAuthority::ScanPinned, 100)
            .unwrap();
        let map = native.scene.coordinator.scan_learned_exe_map();
        assert_eq!(
            map.get(&(dev, ino)),
            Some(&path.to_string_lossy().into_owned()),
            "the admitted caller's probed maps identity is exposed: {map:?}"
        );
        assert_eq!(
            map.len(),
            1,
            "the default caller's placeholder path probes nothing: {map:?}"
        );
    }

    /// The learned-path probe runs once per distinct caller path no
    /// matter how many backfills rebuild the map: two callers
    /// sharing one binary probe it once, a second build probes
    /// nothing new, and a caller admitted later probes only its own
    /// path.
    #[test]
    fn exe_probe_cache_probes_each_path_once() {
        use std::cell::RefCell;
        let dir = tempfile::tempdir().unwrap();
        let (path_a, _, _) = staged_tool(&dir, "tool-a");
        let (path_b, _, _) = staged_tool(&dir, "tool-b");
        let (path_c, _, _) = staged_tool(&dir, "tool-c");
        let pair_of = |path: &std::path::PathBuf| {
            (
                path.to_string_lossy()
                    .bytes()
                    .fold(0u64, |sum, byte| sum.wrapping_add(u64::from(byte))),
                7,
            )
        };
        let (mut native, _) = NativeScene::new();
        for (pid, path) in [(9u32, &path_a), (10, &path_a), (11, &path_b)] {
            native.scene.source.spawn(pid, 100);
            native.scene.source.exec(pid, 101, path.to_str().unwrap());
            native
                .scene
                .coordinator
                .adapter
                .admit(pid, ImageAuthority::ScanPinned, 100)
                .unwrap();
        }
        let counts: RefCell<HashMap<String, usize>> = RefCell::new(HashMap::new());
        let probe = |path: &str| {
            *counts.borrow_mut().entry(path.to_string()).or_default() += 1;
            Some((pair_of(&PathBuf::from(path)).0, 7))
        };
        let mut cache = HashMap::new();
        let build = |native: &NativeScene,
                     cache: &mut HashMap<String, Option<(u64, u64)>>,
                     probe: &dyn Fn(&str) -> Option<(u64, u64)>| {
            InventoryCoordinator::scan_exe_identities_cached(
                &native.scene.coordinator.adapter,
                cache,
                probe,
            )
        };
        let first = build(&native, &mut cache, &probe);
        assert_eq!(
            first.get(&pair_of(&path_a)),
            Some(&path_a.to_string_lossy().into_owned())
        );
        assert_eq!(
            first.get(&pair_of(&path_b)),
            Some(&path_b.to_string_lossy().into_owned())
        );
        native.scene.source.spawn(12, 100);
        native.scene.source.exec(12, 101, path_c.to_str().unwrap());
        native
            .scene
            .coordinator
            .adapter
            .admit(12, ImageAuthority::ScanPinned, 100)
            .unwrap();
        let second = build(&native, &mut cache, &probe);
        assert_eq!(
            second.get(&pair_of(&path_c)),
            Some(&path_c.to_string_lossy().into_owned()),
            "a caller admitted later joins the map: {second:?}"
        );
        for (path, count) in counts.borrow().iter() {
            assert_eq!(*count, 1, "path {path} probes exactly once");
        }
        assert!(
            counts.borrow().len() >= 3,
            "every staged path probed: {:?}",
            counts.borrow().keys().collect::<Vec<_>>()
        );
    }

    /// A full probe cache stops retaining: the overflow tail probes
    /// per build, still correct, while retained entries keep hitting.
    #[test]
    fn exe_probe_cache_overflow_probes_per_build() {
        use std::cell::Cell;
        let dir = tempfile::tempdir().unwrap();
        let (path_a, _, _) = staged_tool(&dir, "tool-a");
        let (mut native, _) = NativeScene::new();
        native.scene.source.spawn(9, 100);
        native.scene.source.exec(9, 101, path_a.to_str().unwrap());
        native
            .scene
            .coordinator
            .adapter
            .admit(9, ImageAuthority::ScanPinned, 100)
            .unwrap();
        let mut cache = HashMap::new();
        for index in 0..DEFAULT_MAX_EXE_PROBE_CACHE_ENTRIES {
            cache.insert(format!("/dummy/{index}"), None);
        }
        let probes = Cell::new(0usize);
        let probe = |path: &str| {
            probes.set(probes.get() + 1);
            Some((path.len() as u64, 7))
        };
        for _ in 0..2 {
            let map = InventoryCoordinator::scan_exe_identities_cached(
                &native.scene.coordinator.adapter,
                &mut cache,
                probe,
            );
            assert!(
                map.values().any(|path| path == path_a.to_str().unwrap()),
                "the overflow path still joins the map: {map:?}"
            );
        }
        // Two builds over the admitted callers (the staged tool plus
        // the scene's own callers), none retained past the cap.
        let callers = native
            .scene
            .coordinator
            .adapter
            .records()
            .filter(|record| record.exe.as_ref().is_some_and(|exe| exe.path.is_some()))
            .count();
        assert_eq!(probes.get(), 2 * callers);
        assert_eq!(cache.len(), DEFAULT_MAX_EXE_PROBE_CACHE_ENTRIES);
    }

    /// LIM-1: the exe-probe cache cap mirrors the default caller
    /// bound (one entry per admitted caller at most) and is never
    /// lowered.
    #[test]
    fn exe_probe_cache_cap_is_pinned() {
        assert_eq!(DEFAULT_MAX_EXE_PROBE_CACHE_ENTRIES, 4_096);
    }

    fn staged_tool(dir: &tempfile::TempDir, name: &str) -> (std::path::PathBuf, u64, u64) {
        let path = dir.path().join(name);
        std::fs::write(&path, b"tool").unwrap();
        let (dev, ino) = crate::discovery::unbound_exe::real_maps_identity(path.to_str().unwrap())
            .expect("the staged tool maps");
        (path, dev, ino)
    }

    /// The concise executable line groups unidentified callers by
    /// executable with call counts and pids; the count headline
    /// stays byte-identical beside it.
    #[test]
    fn concise_names_unidentified_executables_grouped_with_counts() {
        let dir = tempfile::tempdir().unwrap();
        let (_, adev, aino) = staged_tool(&dir, "tool-a");
        let (_, bdev, bino) = staged_tool(&dir, "tool-b");
        let (mut native, _) = NativeScene::new();
        native
            .scene
            .coordinator
            .set_exe_index_dirs(vec![dir.path().to_path_buf()]);
        native.execs(vec![
            exec_record(41, 9, 100, adev, aino),
            exec_record(42, 10, 100, bdev, bino),
            exec_record(43, 11, 100, adev, aino),
        ]);
        let first = native.row(41, 1, 9, 210, 0);
        let second = native.row(42, 1, 10, 220, 0);
        let third = native.row(43, 1, 11, 230, 0);
        native.witness(vec![first, second, third]);
        let (text, _) = slice_one_views(&native);
        let line = "unidentified executables: tool-a (2 calls, host pids 9, 11); tool-b (1 call, host pid 10)";
        assert!(
            text.lines().any(|candidate| candidate == line),
            "concise groups by executable:\n{text}"
        );
        let headline = "unidentified callers: at least 3 calls from 3 caller processes never identified (exited or never scanned); host pids 9, 10, 11 (not running now or never scanned)";
        assert!(
            text.lines().any(|candidate| candidate == headline),
            "the count headline stays byte-identical:\n{text}"
        );
    }

    /// Concise ambiguity: two teacher spellings for one pair keep
    /// the executable name first with an `(ambiguous: <path>,
    /// <path>)` marker listing the candidates' full paths; the
    /// count headline still counts one caller, and JSON keeps the
    /// path with the additive ambiguity keys. The hardlinked pair
    /// shares its mapped identity like snapshot clones share
    /// theirs.
    #[test]
    fn concise_marks_an_ambiguous_executable_without_changing_counts() {
        let dir = tempfile::tempdir().unwrap();
        let first = dir.path().join("tool-a");
        std::fs::write(&first, b"tool").unwrap();
        let second = dir.path().join("tool-b");
        std::fs::hard_link(&first, &second).unwrap();
        let (dev, ino) = crate::discovery::unbound_exe::real_maps_identity(first.to_str().unwrap())
            .expect("the staged tool maps");
        let (mut native, _) = NativeScene::new();
        native.scene.coordinator.set_exe_index_dirs(Vec::new());
        for (pid, path) in [(20u32, &first), (21, &second)] {
            native.scene.source.spawn(pid, 100);
            native.scene.source.exec(pid, 101, path.to_str().unwrap());
            native
                .scene
                .coordinator
                .adapter
                .admit(pid, ImageAuthority::ScanPinned, 100)
                .unwrap();
        }
        native.execs(vec![exec_record(41, 9, 100, dev, ino)]);
        native.witness(vec![native.row(41, 1, 9, 210, 0)]);
        let (text, document) = slice_one_views(&native);
        let line = format!(
            "unidentified executables: tool-a (ambiguous: {}, {}) (1 call, host pid 9)",
            first.display(),
            second.display()
        );
        assert!(
            text.lines().any(|candidate| candidate == line),
            "concise keeps the name first with the candidates' full paths:\n{text}"
        );
        let headline = "unidentified callers: at least 1 call from 1 caller process never identified (exited or never scanned); host pids 9 (not running now or never scanned)";
        assert!(
            text.lines().any(|candidate| candidate == headline),
            "the caller stays one caller:\n{text}"
        );
        assert_eq!(document["modules"][0]["unbound_use"]["images"], 1);
        let exe = &document["modules"][0]["unbound_use"]["executables"][0];
        assert_eq!(exe["resolution"], "scan_learned");
        assert_eq!(exe["exe"], serde_json::json!(first.to_string_lossy()));
        assert_eq!(exe["identity_ambiguous"], true);
        assert_eq!(
            exe["identity_candidates"],
            serde_json::json!([first.to_string_lossy(), second.to_string_lossy()]),
            "JSON lists both candidates: {exe}"
        );
    }

